#include <lightoverleaf/session/inbound/iksessions.h>
#include <lightoverleaf/session/outbound/iksessionstore.h>
#include <lightoverleaf/session/domain/ksessionpolicy.h>
#include <sstream>
namespace lightoverleaf::session {namespace{std::string join(const std::vector<std::string>&v){std::string r;for(auto&s:v){if(!r.empty())r+='\n';r+=s;}return r;}std::vector<std::string>split(const std::string&v){std::istringstream i(v);std::string s;std::vector<std::string>r;while(std::getline(i,s))if(!s.empty())r.push_back(s);return r;}}
class KSessions final:public IKSessions{public:explicit KSessions(std::shared_ptr<IKSessionStore>s):m_store(std::move(s)){}KResult<std::optional<KSessionState>>restore()const override{auto r=m_store->load();if(auto*e=std::get_if<KError>(&r))return *e;auto o=std::get<std::optional<KStoredSession>>(r);if(!o)return std::optional<KSessionState>{};return std::optional<KSessionState>{KSessionState{o->m_workspaceRoot,split(o->m_openFiles),o->m_activeFile,o->m_sidebarWidth,o->m_previewOpen}};}
KResult<bool>save(const KSessionState&v)override{if(!validSessionText(v.m_workspaceRoot,4096)||v.m_openFiles.size()>64||!validSessionText(v.m_activeFile,4096)||v.m_sidebarWidth<180||v.m_sidebarWidth>600)return KError{KErrorCode::InvalidArgument,"session.invalid",false};for(auto&s:v.m_openFiles)if(!validSessionText(s,4096)||s.find('\n')!=std::string::npos)return KError{KErrorCode::InvalidArgument,"session.invalid",false};return m_store->save({v.m_workspaceRoot,join(v.m_openFiles),v.m_activeFile,v.m_sidebarWidth,v.m_previewOpen});}KResult<std::vector<std::string>>history()const override{return m_store->history();}private:std::shared_ptr<IKSessionStore>m_store;};
std::shared_ptr<IKSessions>createSessions(std::shared_ptr<IKSessionStore>s){return s?std::make_shared<KSessions>(std::move(s)):nullptr;}}
